const text = $input.first().json.text;

// ===== TRACKING NUMBERS =====
const trackingNumbers = text.match(/1Z[A-Z0-9]{16}|\b\d{10,15}\b/g) || [];
const filteredTracking = trackingNumbers.filter(t => {
  if (t.length < 10) return false;
  if (/^7\d{11,12}$/.test(t)) return false;
  if (/^[0-9]{10}$/.test(t) && parseInt(t) < 1000000000) return false;
  const escaped = t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  if (new RegExp(`[(/]${escaped}[)/]`).test(text)) return false;
  return true;
});

// ===== CARRIER + TRACKING LINKS =====
const hasUPS = filteredTracking.some(t => t.startsWith('1Z'));
const hasFedEx = filteredTracking.some(t => !t.startsWith('1Z'));
let carrier = 'Unknown';
if (hasUPS && !hasFedEx) carrier = 'UPS Ground';
else if (hasFedEx && !hasUPS) carrier = 'FedEx Freight';
else if (hasUPS && hasFedEx) carrier = 'UPS Ground + FedEx Freight';

const trackingLinks = filteredTracking.map(t => {
  if (t.startsWith('1Z')) {
    return `https://www.ups.com/track?tracknum=${t}`;
  } else {
    return `https://www.fedex.com/fedextrack/?trknbr=${t}`;
  }
}).join('\n');

// ===== CUSTOMER NAME =====
let shipToCompany = null;
let shipToContact = null;
let customerName = null;

const excludedNames = [
  'L2 Global', 'Larry Legend', 'Fanatics', 'Matt Lane',
  'Remit To', 'UPS', 'FedEx', 'USPS', 'Ground', 'Freight',
  'Express', 'Priority', 'Pallet', 'Prepaid', 'TAMPA', 'PAGE',
  'Invoice', 'Date', 'Customer ID', 'BILL TO', 'SHIP TO', 'Shalom Laber'
];

function isExcluded(name) {
  if (!name) return true;
  const lower = name.toLowerCase();
  return excludedNames.some(e => lower.includes(e.toLowerCase()));
}

function cleanName(name) {
  if (!name) return null;
  let c = name.replace(/^(UPS|FedEx|USPS|DHL|Pallet|Prepaid)\s*[-]?\s*(Ground|Freight|Express|Priority|2Day|Overnight)?\s*[-]?\s*/gi, '').trim();
  c = c.replace(/\s+(UW|NFL|NHL|MLB|NBA|Helmet|Jersey|Jrsy|Auto|Vol|Volume|II|I)\s*.*$/i, '').trim();
  c = c.replace(/\s+\d+$/, '').trim();
  return c || null;
}

// Method 1: Business name with known suffix
const bizMatch = text.match(/([A-Z][A-Za-z0-9 '&.-]*(?:Breaks|Breakers|Cards|Sports|Shop|Collectibles|Trading|Hobby|Enterprises|Break))/i);
if (bizMatch && !isExcluded(bizMatch[1])) {
  shipToCompany = bizMatch[1].trim();
}

// Method 2: First line of SHIP TO block — handles "Fanatics/Customer Name" pattern
const shipToMatch = text.match(/SHIP\s*TO[:\s]*\n+([^\n]+)/i);
if (shipToMatch) {
  let candidate = shipToMatch[1].trim();
  if (/^fanatics\//i.test(candidate)) {
    candidate = candidate.split('/')[1].trim();
  }
  if (!isExcluded(candidate)) shipToContact = candidate;
}

// Method 3: Name before product keyword in PO field
if (!shipToCompany && !shipToContact) {
  const poNameMatch = text.match(/([A-Za-z][A-Za-z0-9 '&.-]+?)\s+(?:UW|NFL|NHL|MLB|NBA)\s+/i);
  if (poNameMatch) {
    const n = cleanName(poNameMatch[1]);
    if (n && !isExcluded(n)) customerName = n;
  }
}

// Method 4: Customer PO field — grab name before product keywords
if (!shipToCompany && !shipToContact && !customerName) {
  const poFieldMatch = text.match(/CUSTOMER\s+P\.?O\.?\s*NO\.?[^\n]*\n([^\n]+)/i);
  if (poFieldMatch) {
    const poVal = poFieldMatch[1].trim();
    const nameBeforeProduct = poVal.match(/^([A-Za-z][A-Za-z0-9 '&.-]+?)\s+(?:UW|NFL|NHL|MLB|NBA|UW26|London|Photo|Bat|Jersey|Helmet)/i);
    if (nameBeforeProduct) {
      const n = cleanName(nameBeforeProduct[1]);
      if (n && !isExcluded(n)) customerName = n;
    } else if (!isExcluded(poVal)) {
      customerName = poVal;
    }
  }
}

let shipToName = shipToCompany || shipToContact || customerName;
if (shipToName) shipToName = cleanName(shipToName);

// ===== FANATICS INVOICE NUMBER =====
const invoiceMatch = text.match(/I(\d{8})/);
const invoiceNumber = invoiceMatch ? invoiceMatch[0] : null;

// ===== PRODUCT DESCRIPTION =====
const productLines = [];

// Grab every line that follows a barcode number
const barcodePattern = /\d{12,13}\s*\n([^\n]{10,})/g;
let barcodeMatch;
while ((barcodeMatch = barcodePattern.exec(text)) !== null) {
  const line = barcodeMatch[1].trim();
  // Skip lines that are clearly not product descriptions
  if (
    !line.match(/^(TRACKING|TOTAL|SALES|SHIP|BILL|ORDER|PAGE|Remit)/i) &&
    !line.match(/^\d+\.\d+$/) &&
    line.length > 5
  ) {
    productLines.push(line);
  }
}

// Also catch (DO NOT OPEN) style descriptions
const doNotOpenPattern = /\(DO NOT OPEN\)\s+([^\n]+)/gi;
let doNotOpenMatch;
while ((doNotOpenMatch = doNotOpenPattern.exec(text)) !== null) {
  const line = doNotOpenMatch[1].trim();
  if (!productLines.includes(line)) productLines.push(line);
}

const productDescription = productLines.length > 0 
  ? productLines.join(' / ') 
  : null;

// ===== QTY SHIPPED =====
let qtyShipped = null;
const qtyMatch = text.match(/[A-Z0-9-]+\s+([\d.]+)\s+EA\s+([\d.]+)/);
if (qtyMatch) qtyShipped = parseFloat(qtyMatch[2]);

// ===== ORDER TOTAL =====
let orderTotal = null;
const totalMatch = text.match(/TOTAL\s*\n?\s*([\d,]+\.?\d*)/i);
if (totalMatch) orderTotal = parseFloat(totalMatch[1].replace(/,/g, ''));

// ===== ORDER DATE =====
const dateMatch = text.match(/(\d{1,2}\/\d{1,2}\/\d{4})/);
const orderDate = dateMatch ? dateMatch[0] : null;

// ===== CARRIER CLEANUP =====
// Double check carrier against Ship Via field in PDF
if (carrier === 'Unknown' || carrier === 'UPS Ground') {
  if (/UPS\s+2\s+Day/i.test(text)) carrier = 'UPS 2 Day';
  else if (/UPS\s+Ground/i.test(text)) carrier = 'UPS Ground';
  else if (/FedEx\s+Freight/i.test(text)) carrier = 'FedEx Freight';
  else if (/FedEx/i.test(text)) carrier = 'FedEx';
}

return [{
  json: {
    customerName: shipToName,
    invoiceNumber,
    productDescription,
    qtyShipped,
    orderTotal,
    carrier,
    trackingLinks,
    trackingCount: filteredTracking.length,
    trackingNumbers: filteredTracking,
    orderDate
  },
  binary: $input.first().binary
}];
